// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IAgentRegistry} from "./IAgentRegistry.sol";

/// Holds a payment for the life of one job: a payer locks, the payee releases by committing
/// to the output, and anything that stalls exits through timeout or dispute.
///
/// The settlement asset is fixed at construction, so a lock carries no token field and there
/// is no path by which a caller can name a different one.
interface IEscrow {
    error ZeroAddress();
    error ZeroAmount();
    error BadTtl();
    error BadStatus();
    error BadRefund();
    error BadBond();
    error NotPayer();
    error NotPayee();
    error NotParty();
    error NotResolver();
    error TooEarly();
    error TooLate();
    error AlreadySet();
    error NotDeployer();
    error TransferMismatch();
    error PartyNotAllowed();
    error PayeeCapExceeded();
    error NotTreasury();
    error NotPendingTreasury();
    error BadFee();
    error NotPauser();
    error InsufficientGas();
    error BelowMinLock();
    error BadMinLock();

    enum LockStatus {
        None,
        Locked,
        Released,
        TimedOut,
        Disputed,
        Cancelled,
        Resolved
    }

    /// `counted` records that this lock has already moved a reputation counter. One lock is
    /// worth one counter, and a release contested inside the dispute window has to pick which
    /// one, and it never writes both.
    struct Lock {
        address payer;
        address payee;
        address disputer;
        bytes32 capabilityId;
        bytes32 inputCommit;
        bytes32 outputCommit;
        string inputURI;
        string outputURI;
        uint128 amount;
        uint64 deadline;
        uint64 releasedAt;
        uint128 bond;
        uint64 disputedAt;
        LockStatus status;
        bool counted;
    }

    event Locked(
        uint256 indexed id,
        address indexed payer,
        address indexed payee,
        bytes32 capabilityId,
        uint128 amount,
        uint64 deadline
    );
    event Released(uint256 indexed id, bytes32 outputCommit);
    event ReleaseFinalized(uint256 indexed id);
    event TimedOut(uint256 indexed id);
    event Disputed(uint256 indexed id, address indexed opener);
    event DisputeBonded(uint256 indexed id, address indexed disputer, uint128 bond);
    event BondReturned(uint256 indexed id, address indexed disputer, uint128 bond);
    event BondForfeited(uint256 indexed id, address indexed disputer, uint128 bond);
    event ResolverRewarded(uint256 indexed id, uint256 indexed disputeId, uint128 amount);
    event ResolverRewardUncredited(uint256 indexed id, uint256 indexed disputeId, uint128 amount);
    event Cancelled(uint256 indexed id);
    event Resolved(uint256 indexed id, uint16 refundBps, uint128 refunded, uint128 paid);
    event ResolverSet(address indexed resolver);
    event RegistrySet(address indexed registry);
    event ReputationCallbackFailed(uint256 indexed id);
    event PayerCreditFailed(uint256 indexed id);
    event TreasuryTransferStarted(address indexed from, address indexed to);
    event TreasuryTransferred(address indexed from, address indexed to);
    event FeesSwept(address indexed to, uint128 amount);
    event DisputeReopened(uint256 indexed id, uint64 deadline);
    event PauserSet(address indexed pauser);
    event DisclosureGranted(
        uint256 indexed id, address indexed grantor, address indexed resolver, bytes32 sliceCommit, bytes ciphertext
    );
    event PaymentOwed(address indexed party, uint128 amount);
    event OwedClaimed(address indexed party, uint128 amount);

    /// Pulls `amount` from the caller and opens a lock the payee can settle until `deadline`.
    /// The deadline has to sit strictly inside `[minTtl, maxTtl]` so neither side can create
    /// a lock that is impossible to answer or one that ties funds up indefinitely, and the
    /// amount has to reach `minLock`.
    ///
    /// Two admission checks stand in front of the transfer: the payee has to be allowed to
    /// trade by the agent registry, when one is wired, and `amount` has to sit inside the cap
    /// the payee's settlement history has earned.
    function lock(
        address payee,
        bytes32 capabilityId,
        bytes32 inputCommit,
        string calldata inputURI,
        uint128 amount,
        uint64 deadline
    ) external returns (uint256 id);

    /// Payee claims the lock by committing to the delivered output. Payment moves in the
    /// same call; there is no second step the payer has to take for the payee to be paid.
    function release(uint256 id, bytes32 outputCommit, string calldata outputURI) external;

    /// Records the release against the payee's history once the dispute window has closed
    /// without a complaint. Permissionless, and the payee has the standing reason to call it:
    /// the cap that gates the next lock is read off exactly these counters.
    function finalizeRelease(uint256 id) external;

    /// Permissionless once the deadline passes. Refunds the payer in full.
    function timeout(uint256 id) external;

    /// Contests a lock. Either party may contest one that is still open and not past its
    /// deadline, which by then is the payer's timeout refund; only the payer may contest one
    /// released inside `disputeWindow`, and that late complaint is recorded against the
    /// payee's history and not ruled on, because the money has already moved.
    ///
    /// Contesting an open lock posts a bond of `disputeBondBps` of the locked amount, which
    /// comes back only if the ruling lands on the disputer's side of the split.
    function dispute(uint256 id) external;

    /// Payee declines the job before the deadline and returns the funds. Cheaper for both
    /// sides than letting the lock run to timeout.
    function cancel(uint256 id) external;

    /// Splits a disputed lock. `refundBps` is the payer's share of what is left after the
    /// resolver fee; the remainder goes to the payee. Only the resolver calls this.
    ///
    /// `shares` is how many resolvers the fee splits between. At zero nobody earned it, so the
    /// fee is not taken and the disputer's bond comes back whatever the ruling.
    function resolve(uint256 id, uint16 refundBps, uint8 shares) external;

    /// Returns a disputed lock the resolvers could not hear to `Locked`, with the deadline
    /// moved out by `minTtl` so the payee can still deliver. The bond comes back. Only the
    /// resolver calls this, when the vote missed quorum.
    function reopen(uint256 id) external;

    /// Pays out what settlements booked to `party` when the settlement asset refused the
    /// transfer at the time, usually because its issuer had frozen the address. Anyone may
    /// call it; the money only ever goes to `party`.
    function claim(address party) external returns (uint128 amount);

    /// Emits a disclosure for one resolver on a disputed lock. Either party may call it. The
    /// escrow stores nothing: the ciphertext is for the named resolver to read off the log.
    function grantDisclosure(uint256 id, address resolver, bytes32 sliceCommit, bytes calldata ciphertext) external;

    /// Stops new locks and new disputes. Every exit stays open. The pauser is the timelock,
    /// so the guardian's brake reaches the escrow.
    function pause() external;
    function unpause() external;
    function setPauser(address pauser) external;

    /// Neither contract can name the other at construction, so the pairing is closed afterwards
    /// from both sides: this call and the resolver's own `setEscrow`. One shot, deployer only,
    /// so it cannot be re-pointed later.
    function setResolver(address resolver) external;

    /// Turns on the party gate, once and permanently. Leaving it unset keeps the registry
    /// optional, which is what a minimal deployment wants.
    function setRegistry(IAgentRegistry registry) external;

    /// Pushes the fees a run of settlements has accrued to the treasury. Permissionless: the
    /// treasury should not need a hot key to be paid, and the destination is not the caller's
    /// to choose.
    function sweepFees() external returns (uint128 amount);

    /// Names the treasury's successor. Only the treasury itself may call it, because a
    /// one-step handover to an address nobody controls would strand the fee revenue. The
    /// successor takes the seat by calling `acceptTreasury`.
    function transferTreasury(address to) external;

    function acceptTreasury() external;

    function getLock(uint256 id) external view returns (Lock memory);

    /// Fees booked against settled locks and not yet swept. Only ever credited from a fee
    /// computed against a settling lock, so it can never reach locked principal or a bond.
    function feesAccrued() external view returns (uint128);

    /// What `claim` would pay `party` now.
    function owed(address party) external view returns (uint128);

    function treasury() external view returns (address);
    function pendingTreasury() external view returns (address);

    function settlementAsset() external view returns (address);
    function reputation() external view returns (address);
    function resolver() external view returns (address);
    function pauser() external view returns (address);
    function paused() external view returns (bool);
    function registry() external view returns (IAgentRegistry);
    function feeBps() external view returns (uint16);
    function resolverFeeBps() external view returns (uint16);
    function disputeBondBps() external view returns (uint16);
    function minTtl() external view returns (uint64);
    function maxTtl() external view returns (uint64);
    function disputeWindow() external view returns (uint64);
    function minLock() external view returns (uint128);
    function nextId() external view returns (uint256);
}

src/interfaces/IMandateAccount.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// A spending mandate held by one account contract: a principal funds it and writes the
/// limits, an agent spends inside them, and the settlement asset never leaves except
/// through the escrow or a principal withdrawal.
///
/// The merchant of a spend is the payee of the resulting escrow lock: one address, named from
/// the two sides of the trade.
///
/// Every amount is denominated in the settlement asset's own units. That is six decimals on
/// USDG, and the native 18-decimal view of the same balance is never read. It is the same money
/// counted twice.
interface IMandateAccount {
    error NotPrincipal();
    error NotPendingPrincipal();
    error NotAgent();
    error IsPaused();
    error IsRevoked();
    error NotYetValid();
    error Expired();
    error PerCallCapExceeded();
    error DailyCapExceeded();
    error MonthlyCapExceeded();
    error MerchantNotAllowed();
    error CapabilityNotAllowed();
    error BadMerkleProof();
    error MerkleGateActive();
    error AllowlistGateActive();
    error BadWindow();
    error BadValidity();
    error BadApprovalThreshold();
    error ApprovalRequired();
    error ApprovalMismatch();
    error ApprovalExpired();
    error ApprovalSpent();
    error BadSignature();
    error BadNonce();
    error AuthorizationExpired();
    error NotEscrow();
    error UnknownSpend();
    error CreditExceedsSpend();
    error TransferMismatch();
    error ZeroAddress();
    error ZeroAmount();
    error ClassNotAllowed();
    error TotalCapExceeded();
    error BadClassMask();
    error BadLane();
    error RouterNotSet();
    error InsufficientOutput();
    error AlreadyPrincipal();

    /// Both windows bind at once. A spend has to clear the per-call cap and leave room in
    /// the daily and the monthly bucket, so the tighter of the two is what an agent feels.
    enum WindowKind {
        Daily,
        Monthly
    }

    /// Which source of truth decides whether a merchant can be paid. Allowlist reads the
    /// per-address mapping; MerkleRoot reads a proof against `merchantRoot`, which keeps a
    /// large roster off chain. Exactly one is live at a time so a revocation cannot be
    /// worked around through the other.
    enum MerchantGate {
        Allowlist,
        MerkleRoot
    }

    /// `spent` and `start` roll forward lazily on the first spend after the window elapses,
    /// so an idle mandate costs nothing to keep open. `epoch` counts those rollovers. A
    /// refund credited back has to name the bucket its allowance came out of, and once the
    /// window has rolled that bucket is gone.
    struct Window {
        uint128 cap;
        uint128 spent;
        uint64 duration;
        uint64 start;
        uint64 epoch;
    }

    /// The complete limit set, written atomically. Partial updates are not offered: a
    /// principal signing a mandate signs all of it, and `version` pins which one is live.
    ///
    /// `approvalThreshold` is the amount at and above which the principal's consent is
    /// required. Zero is rejected with `BadApprovalThreshold`, because it reads as "no
    /// threshold" and means the opposite: a mandate deployed with the field left at its
    /// default would need a signature for every spend and the agent would look broken. One
    /// asks for consent on everything; any value above `perCallCap` asks for it on nothing.
    struct Limits {
        uint128 perCallCap;
        uint128 dailyCap;
        uint128 monthlyCap;
        uint64 dailyWindow;
        uint64 monthlyWindow;
        uint128 approvalThreshold;
        uint64 validFrom;
        uint64 validUntil;
        /// Bit `c` set allows spend class `c`: 0 services, 1 agent hires, 2 eligible stocks.
        /// Zero is refused, because a mandate that allows no class refuses every spend.
        uint32 classMask;
        /// Lifetime ceiling on committed spend, net of refunds. Zero means no lifetime ceiling.
        uint128 totalCap;
        /// Lane 1 is the collateral lane, the only one `CollateralVault` opens a credit line
        /// for; no contract distinguishes 0 from 2.
        uint8 lane;
    }

    struct SpendRequest {
        address merchant;
        bytes32 capabilityId;
        bytes32 inputCommit;
        string inputURI;
        uint128 amount;
        uint64 deadline;
        /// 0 services or 1 agent hires. Must be allowed by `classMask`.
        uint8 spendClass;
    }

    /// A principal's consent to one spend above `approvalThreshold`. `approvalId` is chosen
    /// by the principal and burned on use, so approvals can be issued out of band and
    /// consumed out of order. A burned id stays burned for the life of the account, across
    /// changes of principal. `amount` is a ceiling, not an exact match, which lets a quoted
    /// price settle slightly under without a second round trip.
    struct SpendApproval {
        bytes32 approvalId;
        address merchant;
        bytes32 capabilityId;
        uint128 amount;
        uint64 expiry;
    }

    event PrincipalTransferStarted(address indexed from, address indexed to);
    event PrincipalTransferred(address indexed from, address indexed to);
    event AgentUpdated(address indexed agent);
    event AgentRevoked(address indexed agent);
    event LimitsUpdated(uint64 indexed version, Limits limits);
    event MerchantUpdated(address indexed merchant, bool allowed);
    event MerchantGateUpdated(MerchantGate gate, bytes32 merchantRoot);
    event CapabilityUpdated(bytes32 indexed capabilityId, bool allowed);
    event PausedUpdated(bool paused);
    event DocumentHashUpdated(bytes32 indexed documentHash);
    event Deposited(address indexed from, uint256 amount);
    event Withdrawn(address indexed token, address indexed to, uint256 amount);
    event Spent(
        uint256 indexed escrowId,
        address indexed merchant,
        bytes32 indexed capabilityId,
        uint128 amount,
        uint128 dailySpent,
        uint128 monthlySpent
    );
    event SpendApproved(bytes32 indexed approvalId, address indexed merchant, uint128 amount, uint64 expiry);
    event ApprovalRevoked(bytes32 indexed approvalId);
    event ApprovalConsumed(bytes32 indexed approvalId, uint256 indexed escrowId);
    event SpendCredited(uint256 indexed escrowId, uint128 amount, uint128 dailySpent, uint128 monthlySpent);
    event Bought(address indexed asset, uint128 usdgIn, uint256 amountOut, uint256 quotedPriceE8);
    event RouterUpdated(address indexed router);
    event TreasuryParkUpdated(address indexed treasuryPark);

    /// Locks `request.amount` in the escrow against the mandate. Reverts with
    /// `ApprovalRequired` at or above `approvalThreshold`; those spends go through
    /// `spendApproved`.
    ///
    /// `merchantProof` is read only under `MerchantGate.MerkleRoot` and must be empty
    /// otherwise, so a stale proof cannot be smuggled past an allowlist revocation.
    function spend(SpendRequest calldata request, bytes32[] calldata merchantProof) external returns (uint256 escrowId);

    /// Same path, carrying the principal's consent for an above-threshold spend.
    ///
    /// An empty `signature` means the approval was already registered on chain by
    /// `approveSpend`; otherwise it is an EIP-712 signature over `approval`, accepted from
    /// an EOA or through ERC-1271 so a Safe or a cold wallet can authorise without ever
    /// sending a transaction.
    function spendApproved(
        SpendRequest calldata request,
        bytes32[] calldata merchantProof,
        SpendApproval calldata approval,
        bytes calldata signature
    ) external returns (uint256 escrowId);

    function disputeSpend(uint256 escrowId) external;

    /// Returns unspent allowance to the windows a spend was drawn from. The escrow calls it
    /// when a lock exits without paying the merchant in full, so a daily limit is not
    /// consumed by a payment that never happened. Only the escrow can call it, only against
    /// an escrow id this account opened, and for at most what that spend committed.
    ///
    /// A credit that lands after its window has rolled is dropped. The allowance it consumed
    /// expired with the window, and refilling the live bucket would hand the agent budget the
    /// principal never granted. The two windows are judged apart, so a late refund can still
    /// credit the monthly bucket after the daily one has moved on.
    function creditSpend(uint256 escrowId, uint128 amount) external;

    /// Pulls `amount` of the settlement asset from the caller and reports what arrived. A
    /// plain transfer to this address funds the mandate just as well; this exists so funding
    /// is observable.
    ///
    /// An asset that delivers nothing, or more than it was asked to move, reverts with
    /// `TransferMismatch`. The escrow settles every lock at its face amount, so a mandate
    /// funded in a token that does not move exactly what it is told to would pay one
    /// merchant out of another's lock.
    function deposit(uint256 amount) external;

    /// `token` is free so a mistaken airdrop can be swept out. Only the principal calls it.
    function withdraw(address token, address to, uint256 amount) external;

    function setAgent(address agent) external;
    function revokeAgent() external;

    /// Bumps `version` and re-anchors both windows without clearing what was already spent,
    /// so shortening a window cannot retroactively free a bucket.
    function setLimits(Limits calldata limits) external;

    /// Relayed form of `setLimits`. `nonce` is strictly sequential because limit changes are
    /// ordered by intent: a later mandate must not be overtaken by an earlier one that was
    /// signed but held back.
    function setLimitsWithAuthorization(
        Limits calldata limits,
        uint256 nonce,
        uint64 deadline,
        bytes calldata signature
    ) external;

    function setMerchant(address merchant, bool allowed) external;

    /// Switching to `MerkleRoot` requires a non-zero root; switching back to `Allowlist`
    /// requires a zero one. An empty root under a Merkle gate would deny every merchant.
    function setMerchantGate(MerchantGate gate, bytes32 merchantRoot) external;

    function setCapability(bytes32 capabilityId, bool allowed) external;
    function setPaused(bool paused) external;

    /// Anchors the hash of the off-chain mandate document this account enforces. The
    /// contract never reads it; it exists so an auditor can tie a decision log to the terms
    /// that were live at the time.
    function setDocumentHash(bytes32 documentHash) external;

    function approveSpend(SpendApproval calldata approval) external;
    function revokeApproval(bytes32 approvalId) external;

    /// Names the next principal, who takes the account with `acceptPrincipal`. Refused for the
    /// current principal: a handover to itself revokes nothing it has signed.
    function transferPrincipal(address to) external;
    function acceptPrincipal() external;

    /// What the mandate would decide right now, without spending. `reason` is the selector
    /// of the error `spend` would revert with, or zero when `allowed` is true. The
    /// underwriter quotes this before signing an x402 payment so a refusal costs no gas.
    function previewSpend(address merchant, bytes32 capabilityId, uint128 amount, uint8 spendClass)
        external
        view
        returns (bool allowed, bytes4 reason);

    /// Buys an eligible stock token through the principal's chosen router, under class 2 and
    /// every cap. Unusable until the principal names a router.
    function buy(address asset, uint128 usdgIn, uint128 minOut, uint256 quotedPriceE8)
        external
        returns (uint256 amountOut);

    function setRouter(address router) external;

    /// The treasury lane that covers a USDG shortfall inside `spend` and `buy`. Not on the
    /// first v2 accounts.
    function setTreasuryPark(address treasuryPark) external;
    function treasuryPark() external view returns (address);

    /// Passes a disclosure for one resolver through to the escrow, as the payer of the lock.
    function grantDisclosure(uint256 escrowId, address resolver, bytes32 sliceCommit, bytes calldata ciphertext)
        external;

    function classMask() external view returns (uint32);
    function totalCap() external view returns (uint128);
    function totalSpent() external view returns (uint128);
    function lane() external view returns (uint8);
    function router() external view returns (address);
    function approvalEpoch() external view returns (uint64);

    /// What is left under the lifetime ceiling, or the uint128 maximum when there is none.
    function remainingTotal() external view returns (uint128);

    /// Headroom after lazy window rollover: what an agent can spend now, not what the caps
    /// nominally say.
    function remaining() external view returns (uint128 perCall, uint128 daily, uint128 monthly);

    function principal() external view returns (address);
    function pendingPrincipal() external view returns (address);
    function agent() external view returns (address);
    function settlementAsset() external view returns (address);
    function escrow() external view returns (address);
    function paused() external view returns (bool);
    function revoked() external view returns (bool);
    function version() external view returns (uint64);
    function documentHash() external view returns (bytes32);
    function limits() external view returns (Limits memory);
    function window(WindowKind kind) external view returns (Window memory);
    function perCallCap() external view returns (uint128);
    function approvalThreshold() external view returns (uint128);
    function validFrom() external view returns (uint64);
    function validUntil() external view returns (uint64);
    function merchantGate() external view returns (MerchantGate);
    function merchantRoot() external view returns (bytes32);
    function merchants(address merchant) external view returns (bool);
    function capabilities(bytes32 capabilityId) external view returns (bool);
    function approvals(bytes32 approvalId) external view returns (bool registered, bool spent);

    /// What is still creditable against `escrowId`: what that spend committed, less whatever
    /// has already been returned. Zero for an escrow id this account did not open.
    function creditable(uint256 escrowId) external view returns (uint128);
    function nonce() external view returns (uint256);

    function DOMAIN_SEPARATOR() external view returns (bytes32);

    /// keccak256(
    ///   "Limits(uint128 perCallCap,uint128 dailyCap,uint128 monthlyCap,uint64 dailyWindow,"
    ///   "uint64 monthlyWindow,uint128 approvalThreshold,uint64 validFrom,uint64 validUntil,"
    ///   "uint32 classMask,uint128 totalCap,uint8 lane)"
    /// )
    // forge-lint: disable-next-item(mixed-case-function)
    function LIMITS_TYPEHASH() external pure returns (bytes32);

    /// keccak256(
    ///   "SetLimits(Limits limits,uint256 nonce,uint64 deadline)"
    ///   "Limits(uint128 perCallCap,uint128 dailyCap,uint128 monthlyCap,uint64 dailyWindow,"
    ///   "uint64 monthlyWindow,uint128 approvalThreshold,uint64 validFrom,uint64 validUntil,"
    ///   "uint32 classMask,uint128 totalCap,uint8 lane)"
    /// )
    /// Referenced struct types follow the primary type in alphabetical order, per EIP-712.
    // forge-lint: disable-next-item(mixed-case-function)
    function SET_LIMITS_TYPEHASH() external pure returns (bytes32);

    /// keccak256(
    ///   "SpendApproval(bytes32 approvalId,address merchant,bytes32 capabilityId,"
    ///   "uint128 amount,uint64 expiry)"
    /// )
    // forge-lint: disable-next-item(mixed-case-function)
    function SPEND_APPROVAL_TYPEHASH() external pure returns (bytes32);

    /// keccak256(bytes.concat(keccak256(abi.encode(merchant)))), the double-hashed leaf that
    /// makes a proof for an internal node impossible to forge.
    function merchantLeaf(address merchant) external pure returns (bytes32);
}

src/interfaces/IOracleRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {IStaking} from "../token/interfaces/IStaking.sol";

/// Bonded resolvers rule on disputed escrow locks by commit-reveal vote.
///
/// The bond is what makes a vote cost something: a resolver that stays silent after
/// committing, or reveals a score far from the median, loses part of it. Commit-reveal is
/// what stops the later voters from copying the earlier ones, which would turn a quorum into
/// a single opinion repeated.
///
/// The bond is only half the incentive. The escrow deducts a resolver fee from every lock it
/// settles on a ruling and sends it back here, where it is split between the resolvers whose
/// scores held.
///
/// Bonds are posted in BRSR and rewards are paid in the settlement asset, so a resolver puts
/// the protocol's own token at risk and is paid out of the settlement it ruled on. Neither is
/// ever native value. How much BRSR a resolver has to post is not held here: it is the staking
/// pool's `minBondOf`, read live on every vote, which is what lets governance raise the floor
/// against a falling token without touching a bond.
interface IOracleRegistry {
    error AlreadyRegistered();
    error NotRegistered();
    error NotActive();
    error NotAdmin();
    error NotPendingAdmin();
    error NotEscrow();
    error AlreadySet();
    error NotDeployer();
    error BondTooSmall();
    error BondNotAccepted(uint128 offered, uint256 required);
    error BondLocked();
    error StakingNotSet();
    error StakingAssetMismatch(address found, address expected);
    error UnbondNotRequested();
    error UnbondAlreadyRequested();
    error UnbondNotMatured();
    error RosterFull();
    error DisputeNotFound();
    error DisputeAlreadyOpen();
    error BadStatus();
    error AlreadyCommitted();
    error NoCommitment();
    error AlreadyRevealed();
    error BadReveal();
    error BadScore();
    error CommitWindowClosed();
    error CommitWindowOpen();
    error RevealWindowClosed();
    error RevealWindowOpen();
    error QuorumNotMet();
    error QuorumSuspect();
    error BadConfig();
    error ZeroAddress();
    error ZeroAmount();
    error NothingToClaim();
    error PartyCannotVote();

    enum ResolverStatus {
        None,
        Active,
        Unbonding,
        Exited
    }

    enum DisputeStatus {
        None,
        Committing,
        Revealing,
        Finalized,
        Failed
    }

    /// `maxDeviation` is in score points, not basis points. If more than half the revealed
    /// scores sit further than that from the median, the vote has no centre and the payer is
    /// refunded in full.
    ///
    /// `maxVoters` has to be at least the roster cap of 64, so every seated resolver can vote
    /// and none can be crowded out by whoever commits first. Both windows are at least ten
    /// minutes long.
    struct Config {
        uint64 commitWindow;
        uint64 revealWindow;
        uint64 unbondingPeriod;
        uint8 quorum;
        uint8 maxVoters;
        uint8 maxDeviation;
        uint16 slashBps;
    }

    /// `unbondingAt` is the timestamp the request was made, not the timestamp it matures;
    /// the maturity moves if governance shortens `unbondingPeriod`, and a resolver should
    /// not be able to freeze the old period by requesting early.
    struct Resolver {
        uint128 bond;
        uint64 unbondingAt;
        uint32 finalized;
        uint32 slashes;
        ResolverStatus status;
    }

    /// `rewardShares` is the number of resolvers that revealed inside the deviation band,
    /// fixed when the vote closes and before the escrow pays the fee back. A dispute that
    /// failed has no shares, and the escrow takes no resolver fee from a ruling with none.
    struct Dispute {
        uint256 escrowId;
        uint64 openedAt;
        uint64 commitEndsAt;
        uint64 revealEndsAt;
        uint8 commitCount;
        uint8 revealCount;
        uint8 medianScore;
        uint16 refundBps;
        uint8 rewardShares;
        DisputeStatus status;
    }

    event ResolverRegistered(address indexed resolver, uint128 bond);
    event BondIncreased(address indexed resolver, uint128 amount, uint128 bond);
    event UnbondRequested(address indexed resolver, uint64 maturesAt);
    event UnbondCancelled(address indexed resolver);
    event UnbondCompleted(address indexed resolver, uint128 returned);
    event ResolverSlashed(address indexed resolver, uint256 indexed disputeId, uint128 amount);
    event DisputeOpened(uint256 indexed disputeId, uint256 indexed escrowId, uint64 commitEndsAt);
    event VoteCommitted(uint256 indexed disputeId, address indexed resolver, uint8 commitCount);
    event VoteRevealed(uint256 indexed disputeId, address indexed resolver, uint8 score);
    event DisputeFinalized(uint256 indexed disputeId, uint8 medianScore, uint16 refundBps, uint8 voterCount);
    event DisputeFailed(uint256 indexed disputeId, bytes4 reason);
    event RewardsPosted(uint256 indexed disputeId, uint256 amount, uint8 shares, uint256 perShare);
    event RewardsClaimed(address indexed resolver, uint256 amount);
    event UnallocatedSwept(address indexed slashSink, uint256 amount);
    event SurplusSwept(address indexed slashSink, uint256 amount);
    event ResolverEvicted(address indexed resolver, uint128 returned);
    event ConfigUpdated(Config config);
    event EscrowSet(address indexed escrow);
    event StakingSet(address indexed staking, address indexed bondAsset);
    event SlashSinkUpdated(address indexed slashSink);
    event AdminTransferStarted(address indexed from, address indexed to);
    event AdminTransferred(address indexed from, address indexed to);

    /// Pulls `bond` BRSR from the caller. Registration is permissionless above the staking
    /// pool's floor for that address; the roster is capped so finalisation stays inside a
    /// block.
    function register(uint128 bond) external;

    /// Tops a bond back up. The resulting total has to clear the floor, so a resolver below it
    /// cannot return in instalments that never reach it.
    function increaseBond(uint128 amount) external;

    /// Stops the resolver being drawn into new disputes and starts the cooldown, which has to
    /// outlast the longest dispute a live vote could still slash.
    function requestUnbond() external;

    /// Returns the bond once the cooldown has matured and no vote it committed is still open.
    function completeUnbond() external;

    /// Returns the resolver to active without touching the bond.
    function cancelUnbond() external;

    /// Opened by the escrow when either party contests a lock that still holds its funds. The
    /// commit window starts immediately, never on the first vote, so a resolver cannot stall
    /// the clock by waiting. The parties are recorded, with the payer's principal as it reads
    /// at this moment, so none of them can vote on its own dispute.
    function openDispute(uint256 escrowId, address payer, address payee) external returns (uint256 disputeId);

    /// The payer, the payee and the payer's principal as it read when the dispute opened, all
    /// three barred from voting on it. `principal` is zero for a payer that did not answer.
    function partiesOf(uint256 disputeId) external view returns (address payer, address payee, address principal);

    /// Stops new bonds, new votes and new disputes. Reveals and both settlement paths stay
    /// open, so a dispute already running still finishes. Callable by the admin, which is the
    /// timelock, so the guardian's brake reaches the registry.
    function pause() external;
    function unpause() external;
    function paused() external view returns (bool);

    /// `commitment` is `commitmentHash(disputeId, msg.sender, score, salt)`. The resolver
    /// address is inside the hash so one resolver's commitment cannot be replayed by
    /// another who watched the mempool.
    function commitVote(uint256 disputeId, bytes32 commitment) external;

    function revealVote(uint256 disputeId, uint8 score, bytes32 salt) external;

    /// Permissionless once the reveal window closes, or earlier once every commitment has
    /// been revealed. Takes the median score, slashes the silent and the outliers, and
    /// calls the escrow with the resulting refund split.
    function finalize(uint256 disputeId) external;

    /// Permissionless exit for a dispute that never reached quorum. Reopens the lock through
    /// the escrow, with the bond back to the disputer and a fresh deadline for the payee, so
    /// the lock is never left stranded and an unheard dispute is never a refund.
    function failDispute(uint256 disputeId) external;

    /// Posts the resolver fee the escrow deducted from a settled lock. The escrow transfers
    /// the tokens first and calls this second, inside its own `resolve`. A pot too small to
    /// split between the resolvers who earned it is parked for the sink instead of reverting;
    /// a revert would leave the fee here uncredited until `sweepSurplus`.
    ///
    /// The pot is split evenly between the resolvers that revealed within `maxDeviation` of
    /// the median. Silence and outlier scores earn nothing, which is the same test that
    /// decides slashing.
    function notifyReward(uint256 disputeId, uint256 amount) external;

    /// Pays out everything the caller has accrued across settled disputes. Rewards are pulled
    /// rather than pushed so one resolver that cannot receive tokens cannot block a
    /// settlement for the rest.
    function claimRewards() external returns (uint256 amount);

    /// Sends fees that reached no resolver, plus split dust, to the slash sink. Permissionless
    /// because nothing here is discretionary.
    function sweepUnallocated() external returns (uint256 amount);

    /// Sends settlement asset held beyond `rewardFloat` to the slash sink. Only a transfer
    /// made outside `notifyReward` leaves any. Permissionless for the same reason.
    function sweepSurplus() external returns (uint256 amount);

    function slash(address resolver, uint128 amount) external;

    /// Unseats a resolver with no open vote and returns its bond, so a seat slashed to nothing
    /// or left idle does not hold the capped roster for good. Admin only.
    function evict(address resolver) external;
    function setConfig(Config calldata config) external;
    function setSlashSink(address slashSink) external;

    /// The mirror of the escrow's own `setResolver`. Neither constructor can name the other, so
    /// both halves of the pairing are closed after deployment, once each, by the same deployer.
    function setEscrow(address escrow) external;

    /// Names the staking pool that holds the bond floor, and with it the token bonds are posted
    /// in. That token is read off the pool. One shot, deployer only: the token set is deployed
    /// after this contract, and re-pointing it later would change the currency of bonds already
    /// held. Until it is called nobody can bond.
    function setStaking(address staking) external;

    function transferAdmin(address to) external;
    function acceptAdmin() external;

    /// keccak256(abi.encode(disputeId, resolver, score, salt))
    function commitmentHash(uint256 disputeId, address resolver, uint8 score, bytes32 salt)
        external
        pure
        returns (bytes32);

    /// Maps a quality score to the payer's refund share. Stepped rather than linear because
    /// a resolver judging "the job was not done" and one judging "the job was poor" should
    /// not have to agree on a percentage to agree on an outcome.
    function refundBpsForScore(uint8 score) external pure returns (uint16);

    function getDispute(uint256 disputeId) external view returns (Dispute memory);
    function getResolver(address resolver) external view returns (Resolver memory);
    function disputeIdOf(uint256 escrowId) external view returns (uint256);
    function committedBy(uint256 disputeId, address resolver) external view returns (bytes32);
    function revealedBy(uint256 disputeId, address resolver) external view returns (bool revealed, uint8 score);
    function rewardedBy(uint256 disputeId, address resolver) external view returns (bool);
    function rewardsOf(address resolver) external view returns (uint256);
    function voters(uint256 disputeId) external view returns (address[] memory);

    function config() external view returns (Config memory);

    /// The asset resolver rewards are paid in, which is the one the escrow settled the disputed
    /// lock in. Bonds are `bondAsset` and the two are never the same token.
    function settlementAsset() external view returns (address);

    function escrow() external view returns (address);

    /// The address that deployed this contract, and the only one that can close the two
    /// pairings no constructor could: the escrow and the staking pool.
    function deployer() external view returns (address);

    /// The staking pool that answers `isBondable` and `minBondOf`, and the token it denominates
    /// them in. Both are the zero address until `setStaking` runs, and while they are nobody
    /// can bond.
    function staking() external view returns (IStaking);
    function bondAsset() external view returns (IERC20);

    function slashSink() external view returns (address);
    function admin() external view returns (address);
    function pendingAdmin() external view returns (address);
    function totalBonded() external view returns (uint128);
    function resolverCount() external view returns (uint256);
    function nextDisputeId() external view returns (uint256);

    /// Settlement asset held for rewards not yet claimed or swept, allocated or not. Bonds are
    /// counted by `totalBonded` and held in a different token, so the two cannot overlap.
    function rewardFloat() external view returns (uint256);
    function unallocatedRewards() external view returns (uint256);

    function scoreMax() external pure returns (uint8);
}

